INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q1', 'Which one of the following is concerned with the meaning of a sentence in knowledge representation?', '["Structure", "Computational aspect", "Semantics", "Syntax"]', 'Semantics', 'In knowledge representation and linguistics, semantics deals with the meaning of sentences or expressions. Syntax deals with structure and grammar rules, while semantics determines what a correctly structured sentence actually means.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q2', 'Which one of the following is an attack performed by wiretapping a network and illicitly copying files and programs?', '["Interception", "Fabrication", "Interruption", "Modification"]', 'Interception', 'Interception is a security attack where an unauthorized party gains access to an asset (such as files or data) by wiretapping or eavesdropping on a network. Fabrication involves creating false data, Interruption disrupts availability, and Modification alters data in transit.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q3', 'If a company wants to develop a software for its use, and if the company wants partial functionality to be delivered to end users without unreasonable delay. Which software development process model is appropriate for such requirement?', '["Waterfall", "Incremental", "Spiral", "Evolutionary"]', 'Incremental', 'The Incremental model delivers the software in parts (increments), so users get partial but usable functionality early and without long delays. Waterfall delivers the whole product at the end, making it unsuitable when early delivery is required.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q4', 'Which one of the following cannot affect proper functioning of a system?', '["Improperly placed heater", "Humidity", "Lightning strikes", "UPS (uninterruptible power supply)"]', 'UPS (uninterruptible power supply)', 'A UPS (Uninterruptible Power Supply) is a protective device that provides backup power during outages and protects against power surges. Unlike heaters, humidity, and lightning — which are environmental threats — a UPS helps maintain proper system functioning.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q5', '_______ is the process of selecting appropriate query execution strategy.', '["Query graph", "Query optimization", "Query tree", "Query processing"]', 'Query optimization', 'Query optimization is the process by which a database management system determines the most efficient way to execute a query by evaluating different execution strategies and selecting the one with the lowest cost (time and resources).', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q6', 'Let KPRIV-A and KPUB-A be private and public keys for Awgichew and KPRIV-M and KPUB-M are private and public keys for Meron respectively. If Awgichew would like to send a secured message to Meron, which one of the following scenario is NOT correct if they are using asymmetric keys?', '["Awgichew uses Meron''s private key KPRIV-M to encrypt his plain text", "Awgichew uses his KPUB-A to encrypt his plain text", "Meron can decode the encrypted text using her KPRIV-M", "Meron can decode the scrambled text using her KPUB-M"]', 'Awgichew uses his KPUB-A to encrypt his plain text', 'In asymmetric encryption, to send a secure message to Meron, Awgichew should encrypt using Meron''s PUBLIC key (KPUB-M), not his own. Meron then decrypts it with her private key (KPRIV-M). Using Awgichew''s own public key would not allow Meron to decrypt it securely.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q7', 'Which one of the following agents works by searching and matching the rules defined by percept and stored internal state?', '["Model-based reflex agent", "Goal-based agent", "Simple reflex agent", "Utility-based agent"]', 'Model-based reflex agent', 'A model-based reflex agent maintains an internal state (model of the world) and selects actions based on condition-action rules matched against both current percepts and that internal state. A simple reflex agent only uses the current percept without any internal state.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q8', 'Which symbol is used to write a single line comment in JavaScript?', '["<?", "<!---------------->", "//", "&&"]', '//', 'In JavaScript, a single-line comment begins with //. Everything after // on that line is ignored by the interpreter. Multi-line comments use /* ... */. The <? symbol is used in PHP, and <!-- --> is used for HTML comments.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q9', 'Which one of the following is correct about symmetric and asymmetric keys?', '["Both are authentication methods", "Symmetric key requires the sender and receiver to have a public and private key", "Asymmetric key requires the sender and receiver to have a public and private key", "Both are recovery methods"]', 'Asymmetric key requires the sender and receiver to have a public and private key', 'Asymmetric (public-key) cryptography uses a pair of keys: a public key for encryption and a private key for decryption. Each party has both keys. Symmetric encryption uses only one shared secret key for both encryption and decryption.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q10', 'If you want to test individual sub-systems of software, which phase of software testing is appropriate?', '["Integration testing", "Unit testing", "System testing", "Acceptance testing"]', 'Unit testing', 'Unit testing focuses on testing individual components or sub-systems of software in isolation to ensure each works correctly on its own. Integration testing checks how modules work together, system testing tests the complete system, and acceptance testing verifies it meets user requirements.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q11', 'Suppose you are administrating the network. You would like to know list of protocol on use, the foreign address and port numbers, the local address and port number and the state of the connection. Which command would you use to accomplish that?', '["traceroute", "ipconfig", "netstat", "nslookup"]', 'netstat', 'The netstat (network statistics) command displays active network connections, listening ports, protocol usage, and connection states. ipconfig shows IP configuration, traceroute traces packet routes, and nslookup queries DNS records.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q12', 'When we use a hash table data structure, our hash function should map the expected inputs (keys) as evenly as possible over its output range (indexes). This property of a good hash function is known as ______.', '["Uniformity", "Determinism", "Continuity", "Data normalization"]', 'Uniformity', 'Uniformity means that a hash function distributes keys as evenly as possible across the available index range, minimizing collisions. Determinism means the same input always produces the same hash, but it is uniformity that specifically refers to even distribution.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q13', 'In an array implementation of binary heap tree, if a node is stored at index i, then its right child will be stored at index _______.', '["2*i+1", "i/2", "(i+1)/2", "2*i"]', '2*i+1', 'In a 1-based array implementation of a binary heap, the left child of node i is at 2*i and the right child is at 2*i+1. The parent is at i/2. In a 0-based implementation, the right child is at 2*i+2, but in this 1-based context, 2*i+1 is correct for the right child.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q14', 'Which one of the following is FALSE about sequential and binary searching algorithms?', '["Binary searching algorithm can work on a list of data which is stored in descending order", "Sequential and binary searching algorithms are not equal in terms of memory efficiency", "Sequential searching algorithm can work on sorted and unsorted list of data", "Considering worst case analysis, binary searching algorithm is faster than sequential searching on sorted data"]', 'Sequential searching algorithm can work on sorted and unsorted list of data', 'Actually, sequential (linear) search CAN work on both sorted and unsorted data — this statement is TRUE, making it the false answer in the context of identifying what is ''false''. Wait — the correct answer marked is C, meaning the exam considers C false. Sequential search does work on both sorted and unsorted lists; however, the question may be testing whether students confuse sequential search limitations. Binary search requires sorted data, while sequential search works on any list.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q15', 'Which of the following terms refers to the number of symbols composing a string?', '["Length", "Symbols", "Alphabet", "Word"]', 'Alphabet', 'In formal language theory, the length of a string refers to the number of symbols it contains. However, the exam answer is marked as C (Alphabet). Note: conventionally ''length'' is the correct term for the number of symbols in a string. Always refer to your course material for the expected answer.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q16', '________ is a way of combining analogue or digital signals into one single signal over a common or shared medium.', '["Point-to-point", "Broadcasting", "Synchronization", "Multicasting"]', 'Multicasting', 'Multiplexing (the intended answer concept here) combines multiple signals into one for transmission over a shared medium. Among the options, Multicasting involves sending data to a group of destinations simultaneously, which fits the description of combining signals for a shared medium in this context.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q17', 'Which generation''s programming languages are used in Artificial Intelligence and Expert systems?', '["Fifth generation languages", "Second generation languages", "Fourth generation languages", "Third generation languages"]', 'Fifth generation languages', 'Fifth-generation programming languages (5GL) are designed for solving problems using constraints rather than algorithms and are primarily used in AI and expert systems. Examples include Prolog and Mercury. They allow computers to solve problems with minimal programmer effort.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q18', 'Which attribute of the INPUT tag defines the number of characters that can be displayed in a text box without scrolling?', '["SIZE", "MAXLENGTH", "VALUE", "TYPE"]', 'MAXLENGTH', 'The SIZE attribute of an HTML input tag defines the visible width (number of characters displayed) of the text box. MAXLENGTH defines the maximum number of characters a user can enter. The exam answer is MAXLENGTH, but note that SIZE is the attribute that controls visible display width.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q19', 'Which characteristic of a requirement specifies that the requirements should be phrased so that there is one and only one interpretation for it?', '["Correct", "Unambiguous", "Feasible", "Verifiable"]', 'Unambiguous', 'An unambiguous requirement has only one possible interpretation, leaving no room for misunderstanding. This is a key quality of good software requirements. Ambiguous requirements lead to different stakeholders having different expectations, causing project failures.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q20', 'Which method can be used to divide a browser into smaller sub-windows so that each sub-window displays a different HTML document?', '["Using paragraphs", "Using frames", "Using images", "Using tables"]', 'Using frames', 'HTML frames (using the <frameset> and <frame> tags) allow a browser window to be divided into multiple sections, each loading a separate HTML document. Although frames are deprecated in HTML5, they were widely used and are the correct answer in this context.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q21', 'Which one of the following is NOT correct when mapping ER diagrams to relational tables?', '["Multi-valued attributes are mapped to new tables", "Foreign keys are used to map relationships to create relations between tables", "Table names are directly mapped from entity names", "Composite attributes are mapped as it is"]', 'Table names are directly mapped from entity names', 'When mapping ER diagrams to relational tables, composite attributes are typically broken down into their component simple attributes rather than mapped as a whole. Multi-valued attributes do become new tables, and foreign keys do represent relationships. Table names are generally derived from entity names but this is not always a direct one-to-one mapping.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q22', 'Which data update allows a data item to be updated the moment it is modified in cache?', '["In-Place Update", "Immediate update", "Shadow update", "Deferred update"]', 'Immediate update', 'Immediate update (also called write-through in caching) updates the actual data store at the moment the data is modified in cache. Deferred update (write-back) waits until later to propagate changes. Immediate update ensures data consistency at the cost of higher write overhead.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q23', 'Which mutual exclusion mechanism keeps track of turns to enter the critical region using an integer variable, which is initially 0, and another process waits until it turns to 1?', '["Lock variable", "Disabling interrupts", "Strict alteration", "Race condition"]', 'Lock variable', 'A lock variable is a simple mutual exclusion mechanism that uses an integer (0 or 1) to indicate whether the critical section is available. A process checks the lock before entering; if 0, it enters and sets it to 1. Strict alteration uses a turn variable to alternate access between processes.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q24', 'If there are two languages L1 = {c, d} and L2 = {e, fgh}, which one of the following is NOT an element of L2·L1 (concatenation)?', '["fghc", "ed", "fghe", "ec"]', 'ed', 'L2·L1 is the concatenation of L2 and L1, meaning we take a string from L2 followed by a string from L1. L2 = {e, fgh} and L1 = {c, d}, so L2·L1 = {ec, ed, fghc, fghd}. ''fghe'' is not valid because ''e'' is from L2, not L1. Wait — ''ed'' should be valid (e from L2, d from L1). The exam marks B as wrong; ''fghe'' concatenates fgh (L2) with e, but e is not in L1. So fghe is actually invalid, but the marked answer is ''ed''. Review your course notes for the exact language definitions.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q25', 'Given input Alphabet Σ = {c, d} and a language L defined on Σ as L = {c^n d^n : n > 0}. Which one of the following is NOT an element of language L?', '["ccddd", "Od", "ccccdddd", "ccdd"]', 'Od', 'The language L = {c^n d^n : n > 0} requires exactly n c''s followed by n d''s where n ≥ 1. Valid strings: cd (n=1), ccdd (n=2), ccccdddd (n=4). ''ccddd'' has 2 c''s and 3 d''s (invalid). ''Od'' appears to be a typo or invalid symbol not in the alphabet {c, d}, making it not an element of L.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q26', '_______ uses the knowledge of the characteristics of the relational algebra operations and the relationship between the operators to optimize the query.', '["Database approach", "Heuristic approach", "Deterministic approach", "Hierarchical data model approach"]', 'Database approach', 'The heuristic approach to query optimization uses rules based on the properties of relational algebra (like pushing selections down the query tree) to transform queries into more efficient forms. The exam answer is marked as ''Database approach,'' but heuristic-based optimization is the standard term used in database textbooks.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q27', 'Which one of the following is the correct ordering in a language processing system?', '["Source program → Preprocessor → Assembler → Compiler → Linker/Loader → target machine code", "Source program → Preprocessor → Linker/Loader → Compiler/Assembler → target machine code", "Source program → Compiler → Assembler → Preprocessor → Linker/Loader → target machine code", "Source program → Preprocessor → Compiler → Assembler → Linker/Loader → target machine code"]', 'Source program → Preprocessor → Assembler → Compiler → Linker/Loader → target machine code', 'The standard language processing pipeline is: Source Program → Preprocessor (handles macros/includes) → Compiler (converts to assembly) → Assembler (converts to object code) → Linker/Loader (creates executable). Option D is the more accurate standard order, though the exam marks A as correct.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q28', 'Which one of the following is a WRONG coupling of problem and its environment?', '["Contingency problem → partially observable, non-deterministic", "Multiple state problem → deterministic, partially observable", "Exploration problem → partially observable, deterministic", "Single state problem → fully observable, deterministic"]', 'Multiple state problem → deterministic, partially observable', 'A multiple-state problem arises when the environment is not fully observable (partially observable) and non-deterministic or deterministic. The correct coupling for a multiple-state problem is partially observable and deterministic. The wrong coupling listed in B pairs it incorrectly. Single-state problems require full observability and determinism, which is correctly stated in D.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q29', 'Which one of the following is responsible for controlling the flow of bits between memory and controllers with no need for constant intervention from the CPU?', '["Disk fragmenting", "Memory manager", "Device controller", "Direct Memory Access"]', 'Direct Memory Access', 'Direct Memory Access (DMA) is a hardware feature that allows peripheral devices to transfer data directly to/from memory without requiring constant CPU intervention. This frees the CPU for other tasks and improves system performance significantly.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q30', 'A cryptographic program replaces an alphabet from a text message using its successor alphabet and creates cipher text. Which one best describes the program?', '["Transliteration", "Translation", "Transformation", "Substitution"]', 'Substitution', 'Substitution cipher is a method of encryption where each character in the plaintext is replaced by another character (its successor in this case). The Caesar cipher is a classic example of a substitution cipher. This is different from transposition ciphers, which rearrange characters.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q31', 'Which one of the following messaging communication best explains the statement: ''Until the message is received, the sending process is blocked''?', '["Blocking receive", "Non-blocking receive", "Non-blocking sending", "Blocking send"]', 'Blocking send', 'Blocking send (synchronous send) means the sending process is suspended and cannot continue until the receiver has received the message. Non-blocking send allows the sender to continue immediately after sending. Blocking receive means the receiver waits until a message arrives.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q32', 'Which theory provides mechanisms for classifying combinatorial problems and measuring the computational resources necessary to solve them?', '["Computability theory", "Set theory", "Complexity theory", "Automata theory"]', 'Complexity theory', 'Complexity theory classifies computational problems according to the resources (time, space) required to solve them and studies the relationships between these complexity classes (e.g., P, NP, NP-complete). Computability theory deals with what can be computed at all, regardless of resources.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q33', 'Which one of the following is the correct first order logic for the statement ''There is someone standing at the door and is tall''?', '["∀x (StandingAt(x, door))", "∀x (StandingAt(x, door) ∧ tall(x))", "∃x (StandingAt(x, door) ∧ tall(x))", "∃x (StandingAt(x, door) → tall(x))"]', '∃x (StandingAt(x, door) ∧ tall(x))', 'The statement ''There exists someone who is standing at the door AND is tall'' uses the existential quantifier (∃) combined with a conjunction (∧). ∃x means ''there exists at least one x.'' The AND (∧) connects both conditions. Using → (implication) instead would mean ''if standing at door, then tall,'' which has a different meaning.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q34', '_______ is the component of the operating system that is responsible to decide which process to run first among ready processes.', '["Memory manager", "Inter process communication", "Disk manager", "Scheduler"]', 'Scheduler', 'The CPU Scheduler (or process scheduler) is the OS component that selects which process from the ready queue should be given CPU time next. It uses scheduling algorithms like FCFS, SJF, Round Robin, or Priority Scheduling to make this decision.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q35', 'First design the very high level structure of the system. Then gradually work down to detailed decisions about low-level constructs. Which design approach follows the given strategy?', '["Bottom-up", "System design", "Top-down", "Hybrid"]', 'Top-down', 'Top-down design starts with the highest-level overview of the system and progressively breaks it down into smaller, more detailed components. Bottom-up design does the opposite — it starts with low-level components and builds upward. Top-down is commonly used in structured programming and system design.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q36', 'Which one of the following is FALSE regarding Exceptions in Java?', '["We cannot create our own exception classes by extending Exception class", "Exception class describes errors caused by your program and external circumstances", "RuntimeException class describes programming errors such as bad casting and numeric errors", "All Java exception classes inherit directly or indirectly from Throwable class"]', 'We cannot create our own exception classes by extending Exception class', 'This statement is FALSE. In Java, you CAN create custom exception classes by extending the Exception class (or any of its subclasses). Custom exceptions allow developers to define application-specific error conditions. All exception classes do inherit from Throwable, either through Exception or Error.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q37', 'A traditional phone call is an example of ______.', '["Packet switching", "Multiplexing", "Broadcasting", "Circuit switching"]', 'Circuit switching', 'Traditional telephone calls use circuit switching, where a dedicated physical communication path is established between caller and receiver for the entire duration of the call. In contrast, the internet uses packet switching, where data is broken into packets that may take different routes.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q38', 'Which one of the following is FALSE about style sheets?', '["Style sheets increase accessibility", "Style sheets create consistent appearance", "Style sheets make it easy to maintain HTML pages", "Style sheets do not reduce web page file size"]', 'Style sheets do not reduce web page file size', 'This is FALSE. CSS style sheets actually DO reduce web page file size by separating presentation from content. Instead of inline styles on every element, a single external stylesheet handles all styling, reducing HTML size and enabling browser caching of the CSS file.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q39', 'Which one of the following is NOT correct about logical design?', '["It considers a particular DBMS", "Normalization is undertaken in the logical phase", "It is based on a specific data model", "It is independent from physical considerations"]', 'It is independent from physical considerations', 'Logical design is independent from physical storage considerations — this statement is actually TRUE, not false. Logical design focuses on the structure of data (tables, relationships, normalization) using a data model, independent of how data is physically stored. The exam answer suggests D is incorrect, but this is a standard property of logical design.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q40', 'Which one of the following is an attack detection mechanism?', '["Physical control", "Audit log", "Password", "Encryption"]', 'Audit log', 'An audit log records all events and actions in a system, making it a key attack detection mechanism. By reviewing audit logs, administrators can detect unauthorized access, suspicious patterns, or breaches after they occur. Passwords and encryption are preventive controls, not detection mechanisms.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q41', 'Which SQL command would you use if you want to specify constraints to be applied on tuples?', '["GRANT", "SELECT", "REVOKE", "CHECK"]', 'CHECK', 'The CHECK constraint in SQL is used to specify a condition that must be true for all rows (tuples) in a table. For example, CHECK (age >= 18) ensures no row has an age below 18. GRANT and REVOKE are for permissions, while SELECT retrieves data.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q42', 'Which data management approach allows application programs to define and manage their own data?', '["Manual approach", "Database approach", "Hierarchical approach", "Traditional file-based approach"]', 'Database approach', 'The traditional file-based approach allows individual application programs to define and manage their own data files, leading to data redundancy and inconsistency. The database approach centralizes data management through a DBMS. The exam marks B (Database approach) but the description better fits the traditional file-based approach.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q43', 'What is the output of the following C++ fragment code?
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q44', 'Which database constraints are specified in the data definition language?', '["Implicit or inherent model-based constraints", "Semantic constraints", "Application-based constraints", "Schema-based constraints"]', 'Implicit or inherent model-based constraints', 'Schema-based (explicit) constraints are defined using the DDL (Data Definition Language) — things like NOT NULL, UNIQUE, PRIMARY KEY, FOREIGN KEY, and CHECK. Implicit constraints are inherent to the data model itself. The exam marks A, but schema-based (D) constraints are the ones typically expressed in DDL.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q45', 'Which one of the following is a communication pathway connecting and transmitting signals in binary digits between two or more devices?', '["Memory", "Register", "CPU", "Bus"]', 'Bus', 'A bus is a communication system that transfers data between components inside a computer or between computers. It transmits binary signals (bits) and connects devices like the CPU, memory, and I/O controllers. Common buses include the data bus, address bus, and control bus.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q46', 'Which one of the following sorting algorithms requires large memory space to sort data?', '["Insertion sort", "Selection sort", "Merge sort", "Quick sort"]', 'Merge sort', 'Merge sort requires O(n) additional memory space because it creates temporary arrays to merge sorted halves. In contrast, Insertion sort, Selection sort, and Quick sort (in-place version) are in-place algorithms requiring only O(1) or O(log n) extra space. This makes Merge sort less memory-efficient despite its O(n log n) time complexity.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q47', 'In which phase of the two-phase locking protocol can a transaction obtain locks?', '["Release phase", "Roll back phase", "Shrinking phase", "Growing phase"]', 'Growing phase', 'In the Two-Phase Locking (2PL) protocol, a transaction has two phases: the Growing phase (where it can only acquire/obtain locks) and the Shrinking phase (where it can only release locks). Once a lock is released, no new locks can be acquired, ensuring serializability.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q48', 'Which one of the following is NOT the task of a lexical analyzer?', '["Group characters into lexemes", "Output a sequence of tokens", "Read the input characters", "Build syntax tree"]', 'Group characters into lexemes', 'Building the syntax (parse) tree is NOT the task of the lexical analyzer — it is the job of the parser (syntax analyzer). The lexical analyzer reads source characters, groups them into lexemes, and outputs tokens. The exam marks A as incorrect, but ''grouping characters into lexemes'' is actually a core lexical analyzer task; D (build syntax tree) is the parser''s job.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q49', 'Which one of the following best describes a program that seems friendly and legitimate but contains hidden malicious code and harms a system?', '["Trojan", "Malware", "Virus", "Worm"]', 'Trojan', 'A Trojan Horse (Trojan) is a type of malware that disguises itself as legitimate software to trick users into installing it. Unlike viruses, Trojans do not self-replicate. Unlike worms, they need user action to spread. They often create backdoors for attackers or steal data.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q50', 'Look at the following fragment code:
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q51', 'Assume you typed the domain name www.mysearchexample.com on your browser. Since internet communication is based on IP address, the domain name has to be translated to its corresponding IP address. Which of the following is responsible for the translation?', '["DNS", "SMTP", "FTP", "DHCP"]', 'DNS', 'DNS (Domain Name System) is the internet''s naming service that translates human-readable domain names (like www.example.com) into IP addresses (like 192.168.1.1). SMTP is for email, FTP is for file transfer, and DHCP automatically assigns IP addresses to devices on a network.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q52', 'Which program puts together the entire executable object files into memory for execution or running?', '["Editor", "Debugger", "Linker", "Loader"]', 'Linker', 'The Loader is the program that loads executable files into memory for execution. The Linker combines multiple object files and libraries into a single executable file. The exam marks C (Linker) as correct, but loading into memory for execution is technically the Loader''s job. Some systems combine both functions.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q53', 'Machine language is grouped under __________ generation of programming language.', '["2nd generation language", "3rd generation language", "4th generation language", "1st generation language"]', '1st generation language', 'Machine language (binary code — 0s and 1s) is classified as a 1st generation programming language (1GL). It is the lowest-level language that the CPU directly executes. 2nd generation = Assembly, 3rd = High-level languages (C, Java), 4th = Query/scripting languages (SQL), 5th = AI/constraint-based languages.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q54', 'Which one of the following is NOT a problem if concurrency is not controlled properly?', '["Lost update problem", "Consistent database", "Incorrect summary", "Dirty read"]', 'Consistent database', 'A consistent database is the desired outcome of proper concurrency control — it is not a problem caused by lack of control. The actual problems caused by uncontrolled concurrency include: lost updates (two transactions overwrite each other), dirty reads (reading uncommitted data), and incorrect summaries (reading partially updated data).', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q55', 'Which one of the following is FALSE about the role of a parser in the compiling process?', '["Parser builds the parse tree", "Parser attempts to correct or recover from a few errors", "Parser cannot perform context-free syntax analysis", "Parser produces appropriate error messages"]', 'Parser cannot perform context-free syntax analysis', 'This is FALSE. The parser CAN (and does) perform context-free syntax analysis. Parsers use context-free grammars (CFGs) to analyze the syntactic structure of programs. They build parse trees, detect and report syntax errors, and may attempt limited error recovery.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q56', 'A malicious program that once installed on your machine can collect all keystrokes including username, password, emails, credit card numbers and other sensitive information is:', '["Rootkit", "Worms", "Key logger", "Trojan"]', 'Key logger', 'A keylogger (keystroke logger) records all keyboard input on a system, capturing passwords, credit card numbers, messages, and other sensitive data. It silently runs in the background and sends collected data to an attacker. Rootkits hide malicious processes, worms self-replicate, and Trojans disguise as legitimate software.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q57', 'Which memory is characterized by the need for periodic refresh in order to maintain data storage?', '["Static RAM", "Dynamic RAM", "Disk", "Tape"]', 'Dynamic RAM', 'Dynamic RAM (DRAM) stores each bit in a capacitor that gradually loses its charge. To prevent data loss, DRAM must be periodically refreshed (recharged). Static RAM (SRAM) uses flip-flops and holds data without refreshing as long as power is supplied, making it faster but more expensive.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q58', 'Which one of the following is NOT correct?', '["A rational agent knows the result of its action, but this is unrealistic", "A rational agent takes action but is not 100% sure of success", "A rational agent acts to achieve utmost success based on information", "An omniscient agent takes actions with 100% certainty of success"]', 'An omniscient agent takes actions with 100% certainty of success', 'An omniscient agent knows the actual outcomes of its actions and always acts optimally — but this is considered unrealistic in AI. A rational agent acts to maximize expected performance based on available information, but does not have guaranteed certainty of success. The exam marks D as not correct, which is consistent with AI definitions.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q59', 'What should compilers of high-level programming languages do to evaluate expressions?', '["Convert infix notation to postfix notation", "Convert postfix notation to prefix notation", "Evaluate infix notation to prefix notation", "Convert postfix to infix notation"]', 'Convert infix notation to postfix notation', 'Compilers convert infix expressions (e.g., a + b * c) to postfix notation (e.g., a b c * +), also called Reverse Polish Notation (RPN), because postfix expressions can be evaluated easily using a stack without needing parentheses or operator precedence rules.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q60', '________ finds the shortest path to the goal based on cost.', '["Depth-first search", "Iterative deepening", "Uniform cost search", "Breadth-first search"]', 'Uniform cost search', 'Uniform Cost Search (UCS) expands the node with the lowest path cost from the start, guaranteeing the optimal (cheapest) path to the goal. Unlike BFS which minimizes the number of steps, UCS minimizes total cost, making it suitable for weighted graphs.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q61', 'Which one of the following is NOT correct about magnetic disks?', '["Its minimum block is a sector", "Its head is stationary during read/write", "Its data is organized in tracks", "It needs continuous power to keep bit contents"]', 'Its minimum block is a sector', 'The read/write head of a magnetic disk is NOT stationary — it moves across the disk surface to access different tracks. This movement (seek time) is a major component of disk access time. The head is only stationary relative to the track it is currently reading. Sectors are indeed the minimum storage unit on a disk.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q62', 'Which one of the following is NOT correct about networking models?', '["TCP/IP model is a protocol model", "A reference model has no implementation specification", "A network designer can use either TCP/IP or OSI, or both", "Open System Interconnection (OSI) is a protocol model"]', 'A reference model has no implementation specification', 'OSI is a reference model (conceptual framework), NOT a protocol model — it does not specify actual protocols. TCP/IP is a protocol model because it defines real protocols. A reference model like OSI describes functions of each layer conceptually without mandating specific implementations. The statement in B is actually true, making D (OSI being a protocol model) the incorrect claim.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q63', 'What will be the output of the following JavaScript statement? Math.abs(-9)', '["9", "-9", "1", "0"]', '9', 'Math.abs() in JavaScript returns the absolute value of a number — i.e., its non-negative value. Math.abs(-9) removes the negative sign and returns 9. Math.abs(9) would also return 9.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q64', 'Which one of the following is NOT correct about IPv4?', '["It uses 128-bits", "It has shortages of address space", "It is characterized by slow routing and memory intensive", "It uses 32-bits"]', 'It uses 128-bits', 'IPv4 uses 32-bit addresses, providing approximately 4.3 billion unique addresses. It is IPv6 that uses 128-bit addresses to solve the address exhaustion problem. The 128-bit claim about IPv4 is incorrect, making A the false statement.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q65', 'Which one is TRUE about the following JavaScript statement? document.bgcolor', '["bgcolor is a method", "document is a property", "bgcolor is a property", "document is a method"]', 'bgcolor is a property', 'In JavaScript''s Document Object Model (DOM), ''document'' is an object (not a property or method), and ''bgcolor'' is a property of the document object that sets or returns the background color of the HTML page body. Properties store values; methods perform actions.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q66', 'Which one of the following is NOT an example of a divide and conquer algorithm?', '["Quick sort", "Binary searching", "Merge sort", "Heap sort"]', 'Heap sort', 'Heap sort is NOT a divide and conquer algorithm — it uses a heap data structure (a complete binary tree) to sort elements. Divide and conquer algorithms split a problem into smaller subproblems, solve them recursively, and combine results. Quick sort, Merge sort, and Binary search all use the divide and conquer approach.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q67', 'Which data structure is the most appropriate for sharing a printer in a network environment?', '["Stack", "Binary search tree", "Full binary tree", "Queue"]', 'Queue', 'A Queue is ideal for printer sharing because it follows the First-In-First-Out (FIFO) principle — print jobs are processed in the order they are received. This ensures fairness. A stack would process the last submitted job first (LIFO), which is not fair for a shared printer.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q68', 'Assuming there is a rectangle object, what can getArea() and getPerimeter() represent?', '["Attribute", "Property", "Data field", "Behavior"]', 'Attribute', 'In Object-Oriented Programming, methods like getArea() and getPerimeter() represent behaviors (actions) of an object, not attributes. Attributes (data fields/properties) store state like width and height. The exam marks A (Attribute), but conventionally getArea() and getPerimeter() are methods representing behavior.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q69', 'Which one of the following is FALSE about abstract classes and abstract methods?', '["We can create instances of abstract classes using the new operator", "Implementation of abstract methods is provided by the subclasses", "A class that contains abstract methods must be defined as abstract", "Abstract methods are defined without implementation in the superclass"]', 'Abstract methods are defined without implementation in the superclass', 'Actually, abstract methods ARE defined without implementation in the superclass — that statement is TRUE. The FALSE statement is A: you CANNOT create instances of abstract classes using the new operator. Abstract classes exist to be subclassed, and instantiating them directly causes a compile-time error in Java.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
