INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q71', 'Which operator is used to create an array in Java?', '["new", "declare", "static", "construct"]', 'new', 'In Java, arrays are objects and are created using the ''new'' keyword. For example: int[] arr = new int[10]; creates an integer array of size 10. The ''new'' operator allocates memory on the heap for the array.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
