INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q73', 'What is the output of the following Java fragment code?
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q74', 'Which one of the following is NOT a transmission impairment?', '["Synchronization", "Crosstalk", "Impulse noise", "Distortion"]', 'Synchronization', 'Transmission impairments are factors that degrade signal quality, including attenuation, distortion, noise (impulse noise), and crosstalk. Synchronization is a timing mechanism used to coordinate sender and receiver — it is not an impairment but a solution to timing problems.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q75', 'Look at the following C++ fragment code:
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q76', 'Which one of the following is FALSE about client-side scripting?', '["Script languages are not full-featured", "Script languages can access client''s hardware", "Script languages have limited capabilities", "Script languages are embedded as plain text, and interpreted by applications"]', 'Script languages can access client''s hardware', 'Client-side script languages (like JavaScript) run in the browser and are sandboxed — they CANNOT directly access the client''s hardware (disk drives, cameras, etc.) for security reasons. This is FALSE. They have limited capabilities by design to protect users from malicious websites.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q77', 'Which one of the following is TRUE about the Queue data structure?', '["Queue data structure applies first come first served policy", "Queue data structure uses last in first out rule", "Queue data structure does not have efficient basic operations", "Queue data structure cannot be implemented using linked list"]', 'Queue data structure applies first come first served policy', 'A Queue follows FIFO (First-In, First-Out) — the first element added is the first to be removed, which is the ''first come, first served'' policy. It can be implemented using both arrays and linked lists. Basic operations (enqueue/dequeue) run in O(1) time, making them efficient.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q78', 'Which one of the following is NOT correct about IP address and DHCP?', '["An IP leased by the DHCP for a host is permanent", "DHCP assures connectivity as users move from location to location", "The IP addresses are chosen from a predetermined range of addresses", "DHCP allows a host to acquire an IP address automatically"]', 'An IP leased by the DHCP for a host is permanent', 'DHCP (Dynamic Host Configuration Protocol) provides IP addresses on a lease basis — the address is temporary and must be renewed periodically. It is NOT permanent. This dynamic allocation allows IP address reuse when devices disconnect. Static (permanent) IPs must be manually configured.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q79', 'Which one of the following is NOT a condition for two operations in a schedule to be said to conflict?', '["If they access the same item X", "If they belong to the same transactions", "If Write_item(X) is at least one of the operations", "If they belong to different transactions"]', 'If they belong to different transactions', 'Two operations conflict if: (1) they belong to DIFFERENT transactions, (2) they access the same data item, and (3) at least one is a write operation. Belonging to the SAME transaction (option B) is the condition that prevents conflict — conflicting operations must come from different transactions, so D is not a ''condition for conflict'' but a requirement.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q80', 'In case of any shutdown during a transaction before commit, which of the following statements is done automatically?', '["View", "Commit", "Rollback", "Flashback"]', 'Rollback', 'If a system shuts down or crashes before a transaction commits, the DBMS automatically performs a ROLLBACK (undo) to restore the database to its state before the transaction began. This ensures atomicity — a transaction either completes fully (commit) or has no effect (rollback).', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q81', 'Which one of the following commands is NOT used for removing (or deleting) a relation from the SQL database?', '["Delete", "Drop", "Remove", "UPDATE"]', 'UPDATE', 'UPDATE modifies existing data in a table — it does NOT delete a relation. DELETE removes rows from a table, DROP removes the entire table (relation) from the database. ''REMOVE'' is not a standard SQL command either, but among these choices, UPDATE is clearly not used for deletion.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q82', 'A system is in a ______ state if there exists a set of transactions such that every transaction in the set is waiting for another transaction in the set.', '["Idle", "Waiting", "Deadlock", "Ready"]', 'Deadlock', 'A deadlock occurs when a set of transactions are each waiting for a resource held by another transaction in the same set, creating a circular wait. No transaction can proceed. Deadlock detection, prevention, and recovery are key concepts in database concurrency control and operating systems.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q83', 'What is a Functional Requirement?', '["Specifies the tasks the program must complete", "Specifies the tasks the program should not complete", "Specifies the tasks the program must not work", "All of the mentioned"]', 'All of the mentioned', 'Functional requirements define what a system should do — the specific behaviors, functions, and tasks the software must perform or must not perform. They describe system features, operations, and interactions. Non-functional requirements deal with how the system performs (performance, security, usability).', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q84', '_________ is a software development life cycle model that is chosen if the development team has less experience on similar projects.', '["Iterative Enhancement Model", "RAD", "Spiral", "Waterfall"]', 'Waterfall', 'The Waterfall model is often recommended for teams with less experience because it has a clear, linear, well-documented process with defined phases (Requirements → Design → Implementation → Testing → Maintenance). Its rigid structure provides guidance, though it lacks flexibility for changing requirements.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q85', 'In which step of SDLC is actual programming of software code done?', '["Development and Documentation", "Maintenance and Evaluation", "Design", "Analysis"]', 'Development and Documentation', 'In the Software Development Life Cycle (SDLC), actual coding/programming takes place during the Development (Implementation) phase. This phase translates the design documents into working source code. Documentation is created alongside the code to explain the system for future maintainers.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q86', 'Software Debugging is known as _________________.', '["Identifying the task to be computerized", "Creating program code", "Creating the algorithm", "Finding and correcting errors in the program code"]', 'Finding and correcting errors in the program code', 'Debugging is the process of identifying, locating, and fixing bugs (errors/defects) in software code. It involves running the program, observing incorrect behavior, tracing the cause, and making corrections. It is distinct from testing (which finds errors) — debugging fixes them.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q87', '_____________ is a probabilistic algorithm where a data packet is sent by the router to any one of its neighbors randomly.', '["Adaptive routing algorithm", "Flooding routing algorithm", "Random walks routing algorithm", "Distributed routing algorithm"]', 'Random walks routing algorithm', 'Random walks routing sends each packet to a randomly chosen neighboring router. While simple, it is inefficient but self-healing. Flooding sends packets to ALL neighbors, adaptive routing adjusts based on network conditions, and distributed routing uses information from neighboring routers to make decisions.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q88', 'Which network address translation protocol solves the task of address resolution using port numbers?', '["Network Address Translation", "Port Address Translation", "Dynamic Address Translation", "Static address translation"]', 'Port Address Translation', 'Port Address Translation (PAT), also called NAT overloading, maps multiple private IP addresses to a single public IP address using different port numbers to distinguish sessions. This allows many devices to share one public IP, solving IPv4 address exhaustion.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q89', '_____________ is responsible for converting the higher level protocol addresses to physical network addresses.', '["Address Resolution Protocol (ARP)", "Reverse Address Resolution Protocol (RARP)", "Bootstrap Protocol (BOOTP)", "Internet Control Message Protocol (ICMP)"]', 'Address Resolution Protocol (ARP)', 'ARP (Address Resolution Protocol) maps a known IP address (logical/network layer address) to the corresponding MAC address (physical/data link layer address). When a device wants to communicate on a local network, it uses ARP to discover the MAC address of the destination device.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q90', 'Given the network address of 172.16.0.0/19, which of the following is correct?', '["It provides 8 subnets, 32 IP addresses each", "It provides 8 subnets, 8,190 hosts each", "It provides 8 subnets, 30 hosts each", "It provides 8 subnets, 2,046 IP addresses each"]', 'It provides 8 subnets, 32 IP addresses each', '172.16.0.0/19 means 19 bits for network. Class B default is /16, so 3 extra bits are borrowed for subnets: 2^3 = 8 subnets. The remaining host bits = 32 - 19 = 13 bits, giving 2^13 - 2 = 8,190 usable hosts per subnet. The exam marks A as correct (32 IP addresses each), but the calculated value is 8,190 hosts. Option B appears more accurate mathematically.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q91', 'A network device that provides the physical interface between a computer and cabling is known as ________.', '["Switch", "Router", "NIC", "Repeater"]', 'NIC', 'A Network Interface Card (NIC) is the hardware component that provides the physical connection between a computer and the network cable (or wireless network). It handles the encoding/decoding of signals and has a unique MAC address for device identification on the local network.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q92', 'Which of the following is NOT the function of a DHCP server?', '["It grants an IP address when it receives a request from a client", "It maintains the information about client configuration parameters", "It maintains a database of available IP addresses", "It grants an IP address when the sender requests from a client"]', 'It grants an IP address when the sender requests from a client', 'Option D is nonsensical — a DHCP server responds to client requests, not sender requests from a client. The correct functions of DHCP include: granting IP addresses to requesting clients, maintaining IP address pools, and storing client configuration parameters (subnet mask, default gateway, DNS server).', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q93', 'Which one of the following is NOT true about the kernel?', '["Kernel is the program that constitutes the central core of the operating system", "Kernel is the first part of the operating system to load into memory during booting", "Kernel is made of various modules which cannot be loaded in a running operating system", "Kernel remains in the memory during the entire computer session"]', 'Kernel is made of various modules which cannot be loaded in a running operating system', 'Modern kernels (like the Linux kernel) support loadable kernel modules (LKMs) that CAN be dynamically loaded and unloaded while the OS is running. This allows adding device drivers or features without rebooting. The statement that modules cannot be loaded in a running OS is therefore FALSE.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q94', 'Which one of the following circuits requires memory to store the state of the output?', '["Combinational circuit", "Sequential circuits", "Logical circuit", "Physical circuit"]', 'Sequential circuits', 'Sequential circuits have memory elements (like flip-flops) that store the current state. Their output depends on both current inputs AND the stored state (previous outputs). Combinational circuits, in contrast, produce outputs based only on current inputs with no memory — no history is retained.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q95', 'From the following grammars, which describes the lexical syntax?', '["Lexical Grammar", "Context-free Grammar", "Syntactic Grammar", "Regular Grammar"]', 'Context-free Grammar', 'Regular grammars (and regular expressions) are used to describe lexical syntax — the patterns for tokens like identifiers, keywords, and literals. Context-free grammars describe the syntactic (phrase) structure of programs. The exam marks B, but Regular Grammar (D) is the standard answer for describing lexical syntax.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q96', 'What is NOT a Functional Requirement?', '["Specifies the tasks the program must complete", "Specifies the tasks the program should not complete", "Specifies the tasks the program must not work", "Doesn''t specify the tasks the program must not work"]', 'Doesn''t specify the tasks the program must not work', 'Non-functional requirements (like performance, security, usability) do not specify specific tasks the program must complete. A functional requirement defines WHAT the system should do — specific functions, behaviors, and operations. Non-functional requirements specify HOW the system should perform those functions.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q97', '_________ is a software development life cycle model that is chosen if the development team has less experience on similar projects.', '["Iterative Enhancement Model", "RAD", "Spiral", "Waterfall"]', 'Waterfall', 'The Waterfall model is sequential and well-structured, making it suitable for less experienced teams as each phase has clear entry and exit criteria. It provides a disciplined approach with detailed documentation, though it is inflexible to changing requirements once a phase is complete.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q98', 'In which step of SDLC is actual programming of software code done?', '["Development and Documentation", "Maintenance and Evaluation", "Design", "Analysis"]', 'Development and Documentation', 'The Development (or Implementation) phase of the SDLC is where programmers write the actual source code based on design specifications. Documentation is prepared alongside the code to describe the system architecture, modules, and functions for future reference and maintenance.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q99', 'Software Debugging is known as _________________.', '["Identifying the task to be computerized", "Creating program code", "Creating the algorithm", "Finding and correcting errors in the program code"]', 'Finding and correcting errors in the program code', 'Debugging refers to the process of finding and fixing defects or bugs in software. A debugger tool helps step through code execution, inspect variables, and identify where the program behaves unexpectedly. It is a critical skill in software development and maintenance.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2016-q100', 'Which of the following is the understanding of software product limitations, learning system-related problems or changes to be done in existing systems beforehand, identifying and addressing the impact of the project on organization and personnel?', '["Software Design", "Feasibility Study", "Requirement Gathering", "System Analysis"]', 'Feasibility Study', 'A Feasibility Study is conducted early in the SDLC to evaluate whether a proposed project is viable. It assesses technical, financial, legal, operational, and schedule feasibility — including understanding existing system limitations, organizational impact, and what changes are needed before committing to full development.', '', 'medium', 'Exit Exam 2016 (Jan)') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
